from modelscope.hub.api import HubApi
api = HubApi()
resp = api.list_repo_tree('libero', 'Liujian1997', 'master', '/')
# It's a dict-like object
if hasattr(resp, 'items'):
    for k, v in resp.items():
        if k == 'Data':
            if isinstance(v, dict) and 'Files' in v:
                for f in v['Files'][:20]:
                    print(f.get('Name', f.get('Path', f)))
            elif isinstance(v, list):
                for item in v[:20]:
                    if isinstance(item, dict):
                        print(item.get('Name', item.get('Path', item)))
                    else:
                        print(item)
            else:
                print(f'Data type: {type(v)}, val: {str(v)[:500]}')
        else:
            print(f'{k}: {v}')
" 2>&1

